Mesh<Point, double> mesh;
    std::vector<RT::Facet> facets;
    rt.facets(std::back_inserter(facets));

    for (auto const &f : facets) {
        if (is_large_facet(rt, f, threshold)) {
            RT::Cell_handle c1 = f.first;
            RT::Cell_handle c2 = rt.adjacent_cell(f);

            if (c2 != nullptr) {
                Point p1 = rt.dual(c1);
                Point p2 = rt.dual(c2);

                unsigned v1_idx = mesh.vertices.size();
                mesh.vertices.push_back(p1);
                unsigned v2_idx = mesh.vertices.size();
                mesh.vertices.push_back(p2);

                double length = std::sqrt(CGAL::squared_distance(p1, p2));
                mesh.push_back({v1_idx, v2_idx}, length);
            }
        }
    }
    return mesh;

